class UploadQuota:
    def __init__(self, monthly_limit_mib: float) -> None:
        self.monthly_limit_bytes = int(monthly_limit_mib * 1024 * 1024)
        # Per-month usage tracking
        self._files = {}  # month -> dict name -> size
        self._usage = {}  # month -> total bytes counted

    def upload(self, name: str, size_bytes: int, month: str) -> None:
        if size_bytes == 0:
            raise ValueError("Cannot upload a file of size 0.")

        if month not in self._files:
            self._files[month] = {}
            self._usage[month] = 0

        files = self._files[month]
        current = self._usage[month]

        if name in files:
            # Re-uploading same name: does not count twice
            # Preserve original counted size; do not increase usage
            files[name] = files[name]
            return

        # Check the limit
        if current + size_bytes > self.monthly_limit_bytes:
            raise ValueError("Upload exceeds the monthly quota.")

        files[name] = size_bytes
        self._usage[month] = current + size_bytes

    def delete(self, name: str, month: str) -> None:
        if month in self._files and name in self._files[month]:
            size = self._files[month].pop(name)
            self._usage[month] -= size

    def used_bytes(self, month: str) -> int:
        return self._usage.get(month, 0)
